import { LiveAnnouncer } from '@angular/cdk/a11y';
import {
  ChangeDetectionStrategy,
  Component,
  Directive,
  Injectable,
  TemplateRef,
  booleanAttribute,
  computed,
  inject,
  input,
  output,
  signal,
} from '@angular/core';
import {
  AvatarComponent,
  BadgeComponent,
  CsButtonDirective,
  ProgressBarComponent,
  ProgressRingComponent,
  SkeletonComponent,
} from '../../foundations';
import { CsDataState, CsDataStateError, CsFormatService, CsMessageTone } from '../../platform';
import { Subject } from 'rxjs';
import { CsMetricSeries } from '../cs-metric-series.interface';

@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'cs-metric-bars',
  templateUrl: './metric-bars.component.html',
  styleUrl: './metric-bars.component.scss',
})
export class MetricBarsComponent {
  readonly series = input.required<readonly CsMetricSeries[]>();
}

html:
@for (series of series(); track series.label) {
  <div>
    <span>{{ series.label }}</span>
    @for (value of series.values; track $index) {
      <i [style.inline-size.%]="value"></i>
    }
  </div>
}

scss:
div {
  display: grid;
  grid-template-columns: 8rem 1fr;
  gap: var(--cs-space-2);
}
i {
  display: block;
  block-size: 0.75rem;
  background: var(--cs-lime-strong);
}
